WITH valid AS (SELECT id, account_id, txn_type, amount, txn_time, is_flagged, CASE WHEN merchant IN ('Starbucks', 'Lazada') THEN 'Core' ELSE 'Other' END AS merchant_group, CAST(amount AS INT) AS amount_int FROM transactions WHERE txn_time >= TIMESTAMP '2023-05-13 17:00:00' AND merchant IS NOT NULL) SELECT *, LAST_VALUE(amount_int) IGNORE NULLS OVER w_running AS last_known_amount_int, MAX(amount_int) OVER (PARTITION BY txn_type ORDER BY CAST(txn_time AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_int_max_90d FROM valid WINDOW w_running AS (ORDER BY amount_int ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
